export function BalanceSum(td) {
    let balance = 0;
    let debit = 0;
    let credit = 0;
    let obj = { }
    td && td.map((accId) => {
        let aaa = accId.account.accountId + "_" + accId.account.code + "_" + accId.account.type;
        if(!obj[aaa]){
            obj[aaa] = 0;
        }
        let sald = accId?.debit*1 - accId?.credit*1;
        debit += accId?.debit*1;
        credit += accId?.credit*1;
        let amm = parseFloatToDecimal(sald,2)*1
        obj[aaa] = parseFloatToDecimal(obj[aaa],2)*1 + parseFloatToDecimal(amm,2)*1 ;
    })
    balance = debit - credit;
    
    return balance;
}



const calcBalanceComprobacion =  () => {
    let mnt = 12;
    //let mnt =  (new Date(getStore("date_range_submayor")?.initDate)).getMonth() + 1;

    let result_params_value = getStore("result_params_value")

    let result = { };

    let incomes = {
        "Ingresos por Ventas":1,
        "Ingresos por Servicio":2
    }
    let balance = 0;
    let codes = {};


    getStore("result_sheet_upd_flds").map(d4=>{
        if(!result[d4]){
            result[d4] = 1;
            let gg = result_params_value[d4];
            let accc = getStore("account_ids")?.[gg];
            if(accc?.clasification === "nominal"){
                if(!codes[accc.code ]){

                    let amm = getPrevBalance(mnt,{account:gg})*1;

                    amm = accc?.type==="credit"? amm*-1:amm;
                    balance = balance + amm;

                    codes[accc.code ] = amm;
                }
            }
        }
    })

    return parseFloatToDecimal(balance,2)*1

}


export function GroupbyDoc33(td) {

    var obj2 = {};
    let hh = [];
    let balance = 0;
    ObjectKeys(td).map((accId) => {

        let aac = accId;
        let subAc = null;

        if(accId.indexOf("_")>=0){
            aac = accId.split("_")[0];
            subAc = accId.split("_")[1];
        }
        let dataAccounts = getStore("account_ids")?.[aac];

      
        



        td?.[accId] && ObjectKeys(td?.[accId]).map((docId) => {
            if(docId!=="saldo"){

                let amm = parseFloatToDecimal(td?.[accId]?.[docId],2)*1


                
                    let itm = {}
                    itm["debit"] = 0;
                    itm["credit"] = 0;
                    itm["document"] = docId;

                    if(dataAccounts.type==="debit"){
                        itm["debit"] = amm;
                        if(amm<0){
                            itm["credit"] =amm *-1;
                            itm["debit"] = 0
                        }
                    }
                    else if(dataAccounts.type==="credit"){
                        itm["credit"] = amm;
                        if(amm<0){
                            itm["debit"] = amm *-1;
                            itm["credit"] = 0
                        }
                    }

                    //itm["saldo"] =  itm["debit"]  - itm["credit"] ;

                    if(!obj2[docId]){
                        obj2[docId] = parseFloatToDecimal(amm,2)*1 ;
                    }else{
                        let subtDoc = parseFloatToDecimal(obj2[docId],2)*1 + parseFloatToDecimal(amm,2)*1 ;
                        obj2[docId] = parseFloatToDecimal(subtDoc,2)*1;
                    }

                    balance = parseFloatToDecimal(balance,2)*1 + parseFloatToDecimal(amm,2)*1 ;

                    //itm["balance"] =  amm;
                    itm["account"] =  dataAccounts;
                    if(subAc){
                        itm["sub_account"] =   getStore("sub_account_ids")?.[subAc];
                    }
                    hh.push(itm);
                }
            
            
            
        })
      

    })


    let resp = [];
    hh.map(f=>{
        if(obj2[f.document] && (f.debit+f.credit!==0)){
            resp.push(f);
        }
    })
    hh = {...[]};
    obj2 = {...{}};
    
    return {resp, balance};
}




export function factorX(type,acc) {
    if(acc==="debit"){
        return type==="debit"?1:-1;
    }
    else{
        return type==="credit"?1:-1;
    }
}












