export const compareCompp = async (td) => {

   
   
    let bal = 0;
    let comp = {}
    let compList = {}

    let accountS = {}
    for(let i in td){
        let item = td[i];
        
        let acc = getStore("account_ids")?.[item.account];
        if(acc){
        
            if(!isNotEmpty(accountS[acc?.accountId])){
                accountS[acc?.accountId] = {
                    saldo : 0,
                    name : acc?.code + " - "+acc?.name,
                    list : []
                };
            }
            if(!isNotEmpty(comp[item.comprobanteId])){
                comp[item.comprobanteId] = 0;
                compList[item.comprobanteId] = []
            }
            

            let ammount = parseFloatToDecimal((item.type === "debit"? 1 : -1 )*item.amount,2)*1
            accountS[acc?.accountId].saldo  = parseFloatToDecimal(accountS[acc.accountId].saldo,2)*1 +  ammount*1;
            accountS[acc?.accountId].list.push([item.comprobanteId,ammount]) 
            
            comp[item.comprobanteId]  = parseFloatToDecimal(comp[item.comprobanteId],2)*1 +  ammount;
            compList[item.comprobanteId].push({
                ammount,
                operationId : item.comprobanteId
            })
        }
    }

    let compWerr = null;
    for(let i2 in comp){
        if(comp[i2]){
            if(!compWerr){
                compWerr = {};
            }
            compWerr[i2] = 1;
        }
    }

    
    // updStore("accountSumaryComprobacion", accountS);

    if(compWerr){
        updStore("comprobante_w_erros", compWerr);
        updStore("has_filter_comp_error", true);
        
    }    

}


