export function GroupbyDocObj(arr1, objL) {
    var obj = {};

    let cmpList = objL;

    if (cmpList && arr1.length > 0) {
      arr1.map((sId) => {
        let s = cmpList?.[sId];
      
        let ddt =  s?.["date"];
        if(ddt && s?.["account"]){
            let keyId = ddt + "_" +  s["comprobanteId"];
            // if(s.account==="Rs1CzHXPTG5TqbmH" && !s.subAccount){}
            if (!obj[keyId]) {
                obj[keyId] = {};
                let ggg = [
                    "date",
                    "description",
                    "entryName",
                    "comprobanteId",
                    "employeeId",
                    
                ]
                ggg.forEach(fld => {
                    obj[keyId][fld] = s[fld];
                });
                obj[keyId]["amount"] = 0;
                obj[keyId]["balance"] = 0;
                obj[keyId]["operations"] = [];
            }
            
            if(s["type"]){
                // obj[keyId]["balance"] =  parseFloatToDecimal(obj[keyId]["balance"],2)*1 +( s["type"] === "credit" ? parseFloatToDecimal(s["amount"],2)*-1: parseFloatToDecimal(s["amount"],2)*1);
                let itm2 = convert4acc(s);
                itm2.debit = itm2.debit*1;
                itm2.credit = itm2.credit*1;
                obj[keyId]["balance"] +=  itm2.debit - itm2.credit ;
                if(itm2.debit*1 !== itm2.credit*1){

                    obj[keyId]["operations"].push(itm2);
                }
                
            }
        }
      });
    }
    else {
      obj = null;
    }

    // validateComprobantes(obj);
    return obj;
  }



