export const calcCompResume = (data) => {
   
   
    let allMnt = Array.from(Array(12).keys());
    let obj = {};
    let objDoc = {};
    let docS = {};
    
    let dataAccounts = getStore("account_ids");

    data.map(cmpId=>{
        let doc = cmpId?.document?.trim();

        
       
        let keyId = cmpId.account;
        let factor = validateAmountAcc(cmpId["type"], dataAccounts[keyId]?.type)
        let amm = factor * cmpId["amount"];
        if(keyId){
            let month = (new Date(cmpId.date)).getMonth();
            if(keyId && !obj[keyId]){
                obj[keyId] = {}
                obj[keyId].saldo = 0;
                allMnt.map(mnt=>{
                    obj[keyId][mnt] = 0;
                })
            }
            let subt = parseFloatToDecimal(obj[keyId][month],2)*1 + parseFloatToDecimal(amm,2)*1 ;
            obj[keyId][month] = parseFloatToDecimal(subt,2)*1;
        }
        if(cmpId.subAccount){
            let keySubId = cmpId.account + "_" + cmpId.subAccount;
            if(keySubId){
                let month = (new Date(cmpId.date)).getMonth();
                if(keySubId && !obj[keySubId]){
                    obj[keySubId] = {}
                    allMnt.map(mnt=>{
                        obj[keySubId][mnt] = 0;
                    })
                }
                let subt = parseFloatToDecimal(obj[keySubId][month],2)*1 + parseFloatToDecimal(amm,2)*1 ;
                obj[keySubId][month] = parseFloatToDecimal(subt,2)*1;
            }
        }
        if(keyId && dataAccounts?.[keyId]?.clasification==="real"){
           
          
            if(keyId && !objDoc[keyId]){
                objDoc[keyId] = {}
                objDoc[keyId].saldo = 0;
            }
            if(keyId && objDoc[keyId] && !objDoc[keyId][doc]){
                objDoc[keyId][doc] = 0;
            }
            let subt = parseFloatToDecimal(objDoc[keyId][doc],2)*1 + parseFloatToDecimal(amm,2)*1 ;
            objDoc[keyId][doc] = parseFloatToDecimal(subt,2)*1;
            
            let subtA = parseFloatToDecimal(objDoc[keyId].saldo,2)*1 + parseFloatToDecimal(amm,2)*1 ;
            objDoc[keyId].saldo = parseFloatToDecimal(subtA,2)*1;
           
            let subtDoc = parseFloatToDecimal(docS[doc],2)*1 + parseFloatToDecimal(amm,2)*1 ;
            docS[doc] = parseFloatToDecimal(subtDoc,2)*1;

           
            if(!docS[doc]){
                docS[doc] = parseFloatToDecimal(amm,2)*1;
            }else{
                let subtDoc = parseFloatToDecimal(docS[doc],2)*1 + parseFloatToDecimal(amm,2)*1 ;
                docS[doc] = parseFloatToDecimal(subtDoc,2)*1;
            }
            

            if(docS?.[doc]===0){
                delete objDoc[keyId][doc];
            }
            if(objDoc?.[keyId]?.[doc]===0){
                delete objDoc[keyId][doc];
            }
            if(objDoc?.[keyId]?.saldo===0){
                delete objDoc[keyId];
            }
        }
        if(cmpId.subAccount){
            let keySubId = cmpId.account + "_" + cmpId.subAccount;
            if(keySubId && !dataAccounts.ignoreGroupByDocs && dataAccounts?.[keyId]?.clasification==="real"){
                
                if(keySubId && !objDoc[keySubId]){
                    objDoc[keySubId] = {}
                    objDoc[keySubId].saldo = 0;
                }
                if(keySubId && objDoc[keySubId] && !objDoc[keySubId][doc]){
                    objDoc[keySubId][doc] = 0;
                }
                
                let subt = parseFloatToDecimal(objDoc[keySubId][doc],2)*1 + parseFloatToDecimal(amm,2)*1 ;
                objDoc[keySubId][doc] = parseFloatToDecimal(subt,2)*1;
                let subtA = parseFloatToDecimal(objDoc[keySubId].saldo,2)*1 + parseFloatToDecimal(amm,2)*1 ;
                objDoc[keySubId].saldo = parseFloatToDecimal(subtA,2)*1;
                
                if(docS?.[doc]===0){
                    delete objDoc[keySubId][doc];
                }
                if(objDoc?.[keySubId]?.[doc]===0){
                    delete objDoc[keySubId][doc];
                }
                if(objDoc?.[keySubId]?.saldo===0){
                    delete objDoc[keySubId];
                }
            }
        }
    })
    return objDoc;
}



